const response = $input.first().json;

if (!Array.isArray(response.records)) {
  throw new Error('Salesforce response does not contain a records array');
}

return response.records.map((lead) => {
  const missingFields = [];

  if (!lead.Website) missingFields.push('Website');
  if (!lead.Industry) missingFields.push('Industry');
  if (lead.NumberOfEmployees == null) {
    missingFields.push('NumberOfEmployees');
  }
  if (lead.AnnualRevenue == null) {
    missingFields.push('AnnualRevenue');
  }

  return {
    json: {
      salesforceLeadId: lead.Id,
      firstName: lead.FirstName || '',
      lastName: lead.LastName || '',
      fullName: [lead.FirstName, lead.LastName]
        .filter(Boolean)
        .join(' '),
      company: lead.Company || '',
      title: lead.Title || '',
      email: lead.Email || '',
      website: lead.Website || null,
      industry: lead.Industry || null,
      numberOfEmployees: lead.NumberOfEmployees ?? null,
      annualRevenue: lead.AnnualRevenue ?? null,
      country: lead.Country || null,
      leadSource: lead.LeadSource || null,
      salesforceStatus: lead.Status || null,
      intentScore: Number(lead.Intent_Score__c ?? 0),
      enrichmentStatus: lead.Enrichment_Status__c || 'Pending',
      description: lead.Description || '',
      missingFields,
      needsEnrichment: missingFields.length > 0
    }
  };
});

const lead = $json;

let industryScore = 0;
let employeeScore = 0;
let revenueScore = 0;
let personaScore = 0;
let intentScorePoints = 0;
let completenessScore = 0;

// 1. Industry fit: maximum 15 points
const targetIndustries = [
  'technology',
  'finance',
  'banking',
  'insurance',
  'consulting',
  'telecommunications'
];

const normalizedIndustry = (lead.industry || '').toLowerCase();

if (targetIndustries.includes(normalizedIndustry)) {
  industryScore = 15;
}

// 2. Company size: maximum 15 points
const employees = lead.numberOfEmployees;

if (employees >= 1000) {
  employeeScore = 15;
} else if (employees >= 200) {
  employeeScore = 10;
} else if (employees >= 50) {
  employeeScore = 5;
}

// 3. Annual revenue: maximum 10 points
const revenue = lead.annualRevenue;

if (revenue >= 100000000) {
  revenueScore = 10;
} else if (revenue >= 25000000) {
  revenueScore = 7;
} else if (revenue >= 5000000) {
  revenueScore = 3;
}

// 4. Buyer persona: maximum 25 points
const normalizedTitle = (lead.title || '').toLowerCase();

const executiveTitles = [
  'chief',
  'cdo',
  'cto',
  'cio',
  'vp',
  'vice president',
  'head',
  'director'
];

const influencerTitles = [
  'manager',
  'lead',
  'senior'
];

if (executiveTitles.some(title => normalizedTitle.includes(title))) {
  personaScore = 25;
} else if (
  influencerTitles.some(title => normalizedTitle.includes(title))
) {
  personaScore = 15;
} else if (normalizedTitle) {
  personaScore = 5;
}

// 5. Intent signal: maximum 25 points
const rawIntentScore = Number(lead.intentScore || 0);

if (rawIntentScore >= 80) {
  intentScorePoints = 25;
} else if (rawIntentScore >= 60) {
  intentScorePoints = 18;
} else if (rawIntentScore >= 40) {
  intentScorePoints = 10;
} else {
  intentScorePoints = 3;
}

// 6. Data completeness: maximum 10 points
const missingFieldCount = Array.isArray(lead.missingFields)
  ? lead.missingFields.length
  : 0;

completenessScore = Math.max(0, 10 - missingFieldCount * 2.5);

// Calculate final score
const icpScore = Math.round(
  industryScore +
  employeeScore +
  revenueScore +
  personaScore +
  intentScorePoints +
  completenessScore
);

// Assign qualification tier
let icpTier;

if (icpScore >= 70) {
  icpTier = 'High';
} else if (icpScore >= 40) {
  icpTier = 'Medium';
} else {
  icpTier = 'Low';
}

return {
  json: {
    ...lead,
    icpScore,
    icpTier,
    scoreBreakdown: {
      industry: industryScore,
      employeeCount: employeeScore,
      annualRevenue: revenueScore,
      buyerPersona: personaScore,
      intentSignal: intentScorePoints,
      dataCompleteness: completenessScore
    },
    requiresAIAnalysis:
      icpScore >= 70 && lead.needsEnrichment === false
  }
};

