const modelResponse = $json;

// Retrieve the original Lead associated with this Gemini response.
const sourceLead = $('Calculate ICP Score').item.json;

// Support different Gemini/n8n response structures.
let rawResponse =
  modelResponse.text ??
  modelResponse.output ??
  modelResponse.mergedResponse ??
  modelResponse.response?.text ??
  modelResponse.content;

// Standard Gemini candidates response.
if (
  !rawResponse &&
  Array.isArray(modelResponse.candidates) &&
  modelResponse.candidates.length > 0
) {
  rawResponse = modelResponse.candidates[0]?.content?.parts
    ?.map(part => part.text || '')
    .join('');
}

if (!rawResponse) {
  throw new Error(
    `Gemini response text was not found. Available fields: ${Object.keys(
      modelResponse
    ).join(', ')}`
  );
}

let parsedResponse;

// Some n8n versions may already return an object.
if (typeof rawResponse === 'object') {
  parsedResponse = rawResponse;
} else {
  let cleanedResponse = String(rawResponse).trim();

  // Remove markdown fences if Gemini adds them.
  cleanedResponse = cleanedResponse
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  // Keep only the JSON object if surrounding text was added.
  const firstBrace = cleanedResponse.indexOf('{');
  const lastBrace = cleanedResponse.lastIndexOf('}');

  if (firstBrace === -1 || lastBrace === -1) {
    throw new Error('Gemini response does not contain a JSON object');
  }

  cleanedResponse = cleanedResponse.slice(firstBrace, lastBrace + 1);

  try {
    parsedResponse = JSON.parse(cleanedResponse);
  } catch (error) {
    throw new Error(`Invalid Gemini JSON: ${error.message}`);
  }
}

// Validate required string fields.
if (
  typeof parsedResponse.qualificationSummary !== 'string' ||
  !parsedResponse.qualificationSummary.trim()
) {
  throw new Error('Gemini qualificationSummary is missing');
}

if (
  typeof parsedResponse.nextBestAction !== 'string' ||
  !parsedResponse.nextBestAction.trim()
) {
  throw new Error('Gemini nextBestAction is missing');
}

// Validate confidence score.
const confidenceScore = Number(parsedResponse.confidenceScore);

if (
  !Number.isInteger(confidenceScore) ||
  confidenceScore < 0 ||
  confidenceScore > 100
) {
  throw new Error(
    `Invalid Gemini confidenceScore: ${parsedResponse.confidenceScore}`
  );
}

// Verify Gemini returned the correct Salesforce Lead ID.
if (
  parsedResponse.salesforceLeadId &&
  parsedResponse.salesforceLeadId !== sourceLead.salesforceLeadId
) {
  throw new Error('Gemini returned a mismatched Salesforce Lead ID');
}

const keySignals = Array.isArray(parsedResponse.keySignals)
  ? parsedResponse.keySignals
  : [];

const riskFlags = Array.isArray(parsedResponse.riskFlags)
  ? parsedResponse.riskFlags
  : [];

return {
  json: {
    ...sourceLead,
    aiQualificationSummary:
      parsedResponse.qualificationSummary.trim(),
    aiNextBestAction:
      parsedResponse.nextBestAction.trim(),
    aiConfidenceScore: confidenceScore,
    aiKeySignals: keySignals,
    aiRiskFlags: riskFlags,
    aiProcessedAt: new Date().toISOString()
  }
};

// The enrichment response may be returned directly or inside "body"
const response = $json.body ?? $json;

// Retrieve the corresponding Lead before the HTTP request
const originalLead = $('Route Leads').item.json;

const success =
  response.success === true &&
  Number(response.statusCode) === 200 &&
  response.company;

if (success) {
  return {
    json: {
      ...originalLead,

      // Enriched company information
      company: response.company.companyName ?? originalLead.company,
      industry: response.company.industry ?? originalLead.industry,
      numberOfEmployees:
        response.company.numberOfEmployees ??
        originalLead.numberOfEmployees,
      annualRevenue:
        response.company.annualRevenue ??
        originalLead.annualRevenue,
      country:
        response.company.headquartersCountry ??
        originalLead.country,

      // Enrichment metadata
      enrichmentSucceeded: true,
      enrichmentStatus: "Completed",
      enrichmentSource:
        response.enrichmentSource ?? "Mock Company Enrichment API",
      enrichedAt: response.enrichedAt ?? new Date().toISOString(),
      enrichmentError: null,

      // Recalculate these after enrichment
      needsEnrichment: false,
      missingFields: [],
      missingFieldCount: 0
    }
  };
}

return {
  json: {
    ...originalLead,

    enrichmentSucceeded: false,
    enrichmentStatus: "Failed",
    enrichmentSource: "Mock Company Enrichment API",
    enrichedAt: new Date().toISOString(),
    enrichmentError:
      response.errorMessage ??
      response.message ??
      "Company enrichment failed",

    enrichmentErrorCode:
      response.errorCode ?? "UNKNOWN_ENRICHMENT_ERROR",

    enrichmentHttpStatus:
      Number(response.statusCode ?? $json.statusCode ?? 500)
  }
};

